package com.alpharip.staffmod.BuildTimelapse.export;
import java.io.*;import java.nio.file.*;import java.util.*;
/** Local versioned export-job metadata store. Loading never starts an export. */
public final class FileExportJobStore {
 private static final int MAX_JOBS=10000;private final File root;
 public FileExportJobStore(File root){if(root==null)throw new IllegalArgumentException("root");this.root=root;}
 public synchronized void save(String projectId,List<ExportJob> jobs)throws IOException{validateId(projectId);if(jobs==null||jobs.size()>MAX_JOBS)throw new IllegalArgumentException("Invalid export job list");ensureRoot();Properties p=new Properties();p.setProperty("format","1");p.setProperty("count",Integer.toString(jobs.size()));for(int i=0;i<jobs.size();i++){ExportJob j=jobs.get(i);if(j==null)throw new IllegalArgumentException("Null export job");ExportSettings s=j.getSettings();String k="job."+i+".";p.setProperty(k+"id",j.getId());p.setProperty(k+"frames",j.getFrames().getPath());p.setProperty(k+"output",j.getOutput().getPath());p.setProperty(k+"format",s.getFormat().name());p.setProperty(k+"fps",Integer.toString(s.getFps()));p.setProperty(k+"width",Integer.toString(s.getWidth()));p.setProperty(k+"height",Integer.toString(s.getHeight()));p.setProperty(k+"settingsOutput",s.getOutput());}writeAtomically(new File(root,projectId+".exports"),p);}
 public synchronized List<ExportJob> load(String projectId)throws IOException{validateId(projectId);File f=new File(root,projectId+".exports");if(!f.isFile())throw new FileNotFoundException(f.toString());Properties p=new Properties();try(InputStream in=new BufferedInputStream(new FileInputStream(f))){p.load(in);}if(!"1".equals(p.getProperty("format")))throw new IOException("Unsupported export job format");int count;try{count=Integer.parseInt(required(p,"count"));}catch(NumberFormatException e){throw new IOException("Invalid export job count",e);}if(count<0||count>MAX_JOBS)throw new IOException("Export job count exceeds limit");List<ExportJob> out=new ArrayList<ExportJob>(count);try{for(int i=0;i<count;i++){String k="job."+i+".";ExportSettings s=new ExportSettings();s.setFormat(ExportSettings.Format.valueOf(required(p,k+"format")));s.setFps(Integer.parseInt(required(p,k+"fps")));s.setResolution(Integer.parseInt(required(p,k+"width")),Integer.parseInt(required(p,k+"height")));s.setOutput(required(p,k+"settingsOutput"));out.add(new ExportJob(new File(required(p,k+"frames")),new File(required(p,k+"output")),s,required(p,k+"id")));}return Collections.unmodifiableList(out);}catch(IllegalArgumentException e){throw new IOException("Invalid export job data for "+projectId,e);}}
 private void ensureRoot()throws IOException{if((!root.exists()&&!root.mkdirs())||!root.isDirectory())throw new IOException("Cannot create export job directory");}
 private static void writeAtomically(File f,Properties p)throws IOException{File tmp=new File(f.getParentFile(),f.getName()+".tmp");try(OutputStream o=new BufferedOutputStream(new FileOutputStream(tmp))){p.store(o,"Build Timelapse export jobs");}try{Files.move(tmp.toPath(),f.toPath(),StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException e){Files.move(tmp.toPath(),f.toPath(),StandardCopyOption.REPLACE_EXISTING);}finally{if(tmp.exists()&&!tmp.delete())tmp.deleteOnExit();}}
 private static String required(Properties p,String k)throws IOException{String v=p.getProperty(k);if(v==null)throw new IOException("Missing export job property: "+k);return v;}
 private static void validateId(String id)throws IOException{if(id==null||!id.matches("[A-Za-z0-9_-]{1,80}"))throw new IOException("Invalid project id");}
}
